class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        ans = 0
        for a in range(min(n, limit) + 1):
            lo = max(0, n - a - limit)
            hi = min(limit, n - a)
            if lo <= hi:
                ans += hi - lo + 1
        return ans

