class Solution {
public:
    long long f(long long x) {
        return x < 0 ? 0 : (x + 2) * (x + 1) / 2;
    }
    int distributeCandies(int n, int limit) {
        long long ans = f(n) - 3LL * f(n - limit - 1)
                      + 3LL * f(n - 2LL * limit - 2)
                      - f(n - 3LL * limit - 3);
        return (int)ans;
    }
};

